```sql
alter table public.org_admins enable row level security;
alter table public.files enable row level security;

-- Helper function to check if current user is an org admin
create or replace function public.is_org_admin(check_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.org_admins
    where user_id = check_user_id
  );
end;
$$ language plpgsql security definer;

-- R1: Users can see their own files. Org admins can see every file.
create policy "Users can view own files, org admins can view all files"
on public.files
for select
to authenticated
using (
  owner_id = auth.uid() 
  or public.is_org_admin(auth.uid())
);

-- R6: Anonymous visitors cannot see anything (no policy for anon)
-- R7: service_role bypasses RLS by default

-- R2: Users can upload files as themselves
-- R2: Org admins can rename and delete any file (except legal holds)
-- R3: Files under legal hold cannot be renamed or deleted
create policy "Users can insert own files, org admins can insert any file"
on public.files
for insert
to authenticated
with check (
  owner_id = auth.uid()
  or public.is_org_admin(auth.uid())
);

create policy "Users can update own files, org admins can update any non-legal-hold file"
on public.files
for update
to authenticated
using (
  (owner_id = auth.uid() and not legal_hold)
  or (public.is_org_admin(auth.uid()) and not legal_hold)
)
with check (
  (owner_id = auth.uid() or public.is_org_admin(auth.uid()))
  and not legal_hold
);

-- R4: Nobody can place or lift legal hold through the app
-- This is enforced by the update policy above which only allows updates
-- when legal_hold is false in the using clause and with check clause
-- The service_role bypasses this and can update legal_hold

-- R2: Users can delete their own files, org admins can delete any non-legal-hold file
create policy "Users can delete own files, org admins can delete any non-legal-hold file"
on public.files
for delete
to authenticated
using (
  (owner_id = auth.uid() and not legal_hold)
  or (public.is_org_admin(auth.uid()) and not legal_hold)
);

-- R5: Nobody can change org_admins through the app
-- No insert, update, delete policies for org_admins table for authenticated/anon roles
-- service_role bypasses RLS by default

-- R6: Ensure anon has no access (explicit deny via no policies)
-- Revoke any default public grants on org_admins
revoke all on public.org_admins from anon, authenticated;
revoke all on public.files from anon, authenticated;

-- Grant minimal necessary access through policies (policies handle the rest)
grant select, insert, update, delete on public.files to authenticated;
grant select on public.org_admins to authenticated;
```

