create or replace function public.can_access_org(p_org_id bigint)
returns boolean
language plpgsql
security definer
as $$
declare
  v_require_sso boolean;
begin
  if auth.role() = 'service_role' then
    return true;
  end if;

  if not exists (
    select 1 from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  ) then
    return false;
  end if;

  select o.require_sso into v_require_sso
  from public.orgs o
  where o.id = p_org_id;

  if v_require_sso is true and not public.has_sso_session() then
    return false;
  end if;

  return true;
end;
$$;

