returns boolean as $$
begin
  return exists (
    select 1 from public.residents
    where unit_id = check_unit_id and user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

create or replace function public.is_unit_accessible(check_unit_id bigint)
returns boolean as $$
declare
  v_building_id bigint;
begin
  select u.building_id into v_building_id from public.units u where u.id = check_unit_id;
  return public.is_building_staff(v_building_id) or public.is_resident(check_unit_id);
end;
$$ language plpgsql security definer;

create or replace function public.is_request_accessible(check_request_id bigint)
returns boolean as $$
declare
  v_unit_id bigint;
begin
  select r.unit_id into v_unit_id from public.requests r where r.id = check_request_id;
  return public.is_unit_accessible(v_unit_id);
end;
