returns boolean as $$
declare
  v_unit_id bigint;
begin
  select r.unit_id into v_unit_id from public.requests r where r.id = check_request_id;
  return public.is_building_staff((select u.building_id from public.units u where u.id = v_unit_id));
end;
$$ language plpgsql security definer;

