  v_seller_id uuid;
  v_ends_at timestamptz;
  v_min_increment numeric(10, 2);
  v_starting_price numeric(10, 2);
  v_highest_bid numeric(10, 2);
  v_highest_bidder uuid;
  v_new_highest_bid numeric(10, 2);
  v_caller_id uuid := auth.uid();
begin
  -- R4: Caller must be signed in
  if v_caller_id is null then
    raise exception 'Caller must be signed in';
  end if;

  -- R4: Auction must exist
  select seller_id, ends_at, min_increment, starting_price, highest_bid, highest_bidder
  into v_seller_id, v_ends_at, v_min_increment, v_starting_price, v_highest_bid, v_highest_bidder
  from public.auctions
  where id = p_auction_id;

  if not found then
    raise exception 'Auction does not exist';
  end if;

  -- R4: Auction must not have ended
