    raise exception 'Auction has ended';
  end if;

  -- R4: Caller cannot be the seller
  if v_seller_id = v_caller_id then
    raise exception 'Cannot bid on your own auction';
  end if;

  -- R4: Amount validation
  if p_amount is null or p_amount <= 0 then
    raise exception 'Invalid bid amount';
  end if;

  if v_highest_bid is null then
    -- No bids yet: must be at or above starting price
    if p_amount < v_starting_price then
      raise exception 'Bid must be at least the starting price';
    end if;
  else
    -- Existing bids: must be above highest bid by at least min_increment
    v_new_highest_bid := v_highest_bid + v_min_increment;
    if p_amount < v_new_highest_bid then
      raise exception 'Bid must be at least % more than the current highest bid', v_new_highest_bid;
    end if;
  end if;

  -- R3: Record the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_caller_id, p_amount, now());

  -- R3: Update auction's highest bid
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_caller_id
  where id = p_auction_id;

  return p_amount;
end;
$$;

